// Event name constants for GetTotalBalance
export const EVENT_WalletGetTotalBalance = "api.wallet.getTotalBalance";

/**
 * Get total balance across all user wallets
 */
export async function getTotalBalance(request: GetTotalBalanceRequest): Promise<GetTotalBalanceResponse> {
  return await api.wallet.getTotalBalance(request);
}

export function useQueryGetTotalBalance<TransformedType = GetTotalBalanceResponse>(
  payload: GetTotalBalanceRequest,
  ops?: CustomUseQueryOptions<GetTotalBalanceResponse, TransformedType>
) {
  return useQuery<GetTotalBalanceResponse, ErrorType, TransformedType, any>({
    queryKey: [EVENT_WalletGetTotalBalance, payload],
    queryFn: async () => {
      return await getTotalBalance(payload);
    },
    retry: false,
    select: (response) => response as TransformedType,
    ...ops
  });
}

export function useMutationGetTotalBalance(opts?: CustomUseMutationOptions<GetTotalBalanceResponse, GetTotalBalanceRequest, any>) {
  return useMutation<GetTotalBalanceResponse, ErrorType, GetTotalBalanceRequest, any>({
    mutationFn: async (request) => {
      return await getTotalBalance(request);
    },
    retry: false,
    ...opts
  });
}

